class MinionTaskingRepositoryTests(unittest.TestCase):
    def setUp(self) -> None:
        self.root = Path(tempfile.mkdtemp(prefix="pal_minion_tasking_test_"))
        self.repository = MinionTaskingRepository(runtime_root=self.root)

    def tearDown(self) -> None:
        shutil.rmtree(self.root, ignore_errors=True)

    def test_prepare_existing_work_order_reactivates_failed_retry(self) -> None:
        pack = TaskContextPack(
            work_order_id="wo_retry_existing",
            goal="retry failed work order",
            instruction="Retry the same work order id.",
            acceptance_criteria=["retry succeeds"],
            metadata={"task_id": "task_retry_existing"},
        )
        self.repository.prepare_pack_for_spawn(pack)
        self.repository.record_minion_event(
            {
                "event_kind": "terminal",
                "work_order_id": "wo_retry_existing",
                "minion_id": "m1",
                "run_id": "r1",
                "payload": {"status": "failed", "summary": "first attempt failed"},
            }
        )
        failed = self.repository.read_work_order("wo_retry_existing")
        self.assertEqual(failed["work_order"]["status"], "failed")
        self.assertTrue(failed["work_order"]["ended_at"])

        self.repository.prepare_pack_for_spawn(pack)

        retried = self.repository.read_work_order("wo_retry_existing")
        self.assertEqual(retried["work_order"]["status"], "active")
        self.assertEqual(retried["work_order"]["ended_at"], "")

    def test_checkpoint_is_milestone_cursor_and_lessons_wait_for_approval(self) -> None:
        module = _plan_module("module_cursor", title="Ship feature")
        module["internal_milestones"] = [
            {"milestone_id": "m1", "title": "Design", "task": "Design the feature.", "acceptance_criteria": ["design done"]},
            {"milestone_id": "m2", "title": "Implement", "task": "Implement the feature.", "acceptance_criteria": ["implementation done"]},
        ]
        plan = _dispatchable_plan_payload(
            plan_id="plan_cursor",
            task_id="task_ship",
            modules=[module],
        )
        pack = self.repository.build_coder_module_pack_from_plan(
            plan,
            module_id="module_cursor",
            work_order_id="wo_cursor",
            goal="ship feature",
        )
        prepared = self.repository.prepare_pack_for_spawn(pack)

        self.assertEqual(prepared.continuity["current_milestone"]["milestone_index"], 0)

        self.repository.record_minion_event(
            {
                "event_kind": "checkpoint",
                "work_order_id": "wo_cursor",
                "minion_id": "m1",
                "run_id": "r1",
                "payload": {"status": "partial", "milestone_index": 0, "summary": "halfway"},
            }
        )
        snapshot = self.repository.read_work_order("wo_cursor")
        self.assertEqual(snapshot["current_milestone"]["milestone_index"], 0)

        self.repository.record_minion_event(
            {
                "event_kind": "checkpoint",
                "work_order_id": "wo_cursor",
                "minion_id": "m1",
                "run_id": "r1",
                "payload": {"status": "completed", "milestone_index": 0, "summary": "design done"},
            }
        )
        snapshot = self.repository.read_work_order("wo_cursor")
        self.assertEqual(snapshot["current_milestone"]["milestone_index"], 1)
        self.assertEqual(snapshot["latest_completed_checkpoint"]["status"], "completed")

        self.repository.record_minion_event(
            {
                "event_kind": "terminal",
                "work_order_id": "wo_cursor",
                "minion_id": "m1",
                "run_id": "r1",
                "payload": {
                    "status": "completed",
                    "summary": "done",
                    "artifacts": [{"path": "/tmp/minion/design.md", "relative_path": "design.md", "role": "primary"}],
                    "primary_artifact": {"path": "/tmp/minion/design.md", "relative_path": "design.md", "role": "primary"},
                    "task_lessons": ["Use the existing milestone cursor."],
                    "system_lessons": ["Maybe promote this pattern later."],
                },
            }
        )
        snapshot = self.repository.read_work_order("wo_cursor")
        self.assertEqual(snapshot["work_order"]["status"], "active")
        self.assertEqual(snapshot["current_milestone"]["milestone_index"], 1)
        self.assertEqual(snapshot["work_order"]["metadata"]["artifacts"][0]["relative_path"], "design.md")
        self.assertEqual(snapshot["work_order"]["metadata"]["primary_artifact"]["relative_path"], "design.md")
        self.assertEqual(snapshot["task_lessons"], [])
        self.assertEqual(snapshot["pending_system_lesson_candidates"], [])

        self.repository.record_minion_event(
            {
                "event_kind": "checkpoint",
                "work_order_id": "wo_cursor",
                "minion_id": "m1",
                "run_id": "r2",
                "payload": {"status": "completed", "milestone_index": 1, "summary": "implement done"},
            }
        )
        self.repository.record_minion_event(
            {
                "event_kind": "terminal",
                "work_order_id": "wo_cursor",
                "minion_id": "m1",
                "run_id": "r2",
                "payload": {"status": "completed", "summary": "all done"},
            }
        )
        snapshot = self.repository.read_work_order("wo_cursor")
        self.assertEqual(snapshot["work_order"]["status"], "completed")

        absorbed = self.repository.absorb_lessons(
            "wo_cursor",
            task_lessons=["Use the existing milestone cursor."],
            system_lessons=["Maybe promote this pattern later."],
            minion_id="m1",
            run_id="r1",
        )

        self.assertEqual(absorbed["status"], "ok")
        snapshot = self.repository.read_work_order("wo_cursor")
        self.assertEqual(snapshot["task_lessons"][0]["lesson_text"], "Use the existing milestone cursor.")
        self.assertEqual(snapshot["pending_system_lesson_candidates"], [])

    def test_recover_stale_running_module_releases_parent_without_completing_module(self) -> None:
        plan = _dispatchable_plan_payload(
            plan_id="plan_recover_stale",
            task_id="task_recover_stale",
            modules=[_plan_module("module_recover_stale")],
        )
        parent = self.repository.build_plan_parent_pack_from_plan(plan, work_order_id="wo_recover_parent")
        self.repository.prepare_pack_for_spawn(parent)
        child_pack = self.repository.next_plan_module_pack("wo_recover_parent", allow_paused=True)
        assert child_pack is not None
        self.repository.prepare_pack_for_spawn(child_pack)

        result = self.repository.recover_stale_running_modules(
            active_child_work_order_ids=set(),
            work_order_id="wo_recover_parent",
            reason="unit test stale child",
        )

        self.assertEqual(result["status"], "recovered")
        parent_snapshot = self.repository.read_work_order("wo_recover_parent")
        plan_execution = parent_snapshot["work_order"]["metadata"]["plan_execution"]
        self.assertEqual(plan_execution["status"], "awaiting_continue")
        self.assertNotIn("active_child_work_order_id", plan_execution)
        self.assertEqual(plan_execution["last_released_child_work_order_id"], child_pack.work_order_id)
        self.assertEqual(parent_snapshot["current_milestone"]["milestone_index"], 0)
        child_snapshot = self.repository.read_work_order(child_pack.work_order_id)
        self.assertEqual(child_snapshot["work_order"]["status"], "failed")
        self.assertTrue(any(item["event_kind"] == "module_recovered" for item in parent_snapshot["recent_ledger"]))

    def test_recover_stale_running_module_keeps_active_child_running(self) -> None:
        plan = _dispatchable_plan_payload(
            plan_id="plan_recover_active",
            task_id="task_recover_active",
            modules=[_plan_module("module_recover_active")],
        )
        parent = self.repository.build_plan_parent_pack_from_plan(plan, work_order_id="wo_recover_active_parent")
        self.repository.prepare_pack_for_spawn(parent)
        child_pack = self.repository.next_plan_module_pack("wo_recover_active_parent", allow_paused=True)
        assert child_pack is not None
        self.repository.prepare_pack_for_spawn(child_pack)

        result = self.repository.recover_stale_running_modules(
            active_child_work_order_ids={child_pack.work_order_id},
            work_order_id="wo_recover_active_parent",
        )

        self.assertEqual(result["status"], "active_child_running")
        parent_snapshot = self.repository.read_work_order("wo_recover_active_parent")
        plan_execution = parent_snapshot["work_order"]["metadata"]["plan_execution"]
        self.assertEqual(plan_execution["status"], "running_module")
        self.assertEqual(plan_execution["active_child_work_order_id"], child_pack.work_order_id)

