    def test_plan_module_child_does_not_inherit_parent_profile_policies(self) -> None:
        plan = _dispatchable_plan_payload(
            plan_id="plan_policy_sanitize",
            task_id="task_policy_sanitize",
            modules=[_plan_module("implementation", title="Implementation")],
        )
        parent = self.repository.build_plan_parent_pack_from_plan(
            plan,
            work_order_id="wo_parent_policy_sanitize",
            workspace={
                "repo_path": str(self.root),
                "source_repo": str(self.root),
                "languages": ["python"],
                "workspace_policy": {"mode": "read_only_repo"},
                "workspace_environment_policy": {"runtime": False, "lsp": True, "write_baseline_config": False},
                "completion_policy": {"evidence": "text_deliverable"},
                "gate_policy": {"gates": ["plan_acceptance"]},
                "output_policy": {"requires_plan_artifact": True},
                "execution_strategy": {
                    "prepare": {"kind": "read_only_repo"},
                    "repair_loop": {"kind": "plan_revision"},
                    "gate": {"kind": "plan_acceptance"},
                },
            },
        )
        self.repository.prepare_pack_for_spawn(parent)

        child = self.repository.next_plan_module_pack("wo_parent_policy_sanitize", allow_paused=True)

        self.assertIsNotNone(child)
        assert child is not None
        self.assertEqual(child.metadata["parent_module_id"], "module_prelude")
        self.assertEqual(child.workspace["source_repo"], str(self.root))
        self.assertEqual(child.workspace["languages"], ["python"])
        for key in (
            "workspace_policy",
            "workspace_environment_policy",
            "completion_policy",
            "gate_policy",
            "output_policy",
            "execution_strategy",
        ):
            self.assertNotIn(key, child.workspace)

        resolved = MinionProfileRegistry(runtime_root=self.root).resolve_pack(child)

        self.assertEqual(resolved.workspace["workspace_policy"]["mode"], "writable_git_branch")
        self.assertEqual(resolved.workspace["completion_policy"]["evidence"], "git_commit")
        self.assertEqual(resolved.workspace["execution_strategy"]["prepare"]["kind"], "git_worktree")
        self.assertEqual(
            resolved.workspace["workspace_environment_policy"],
            {"runtime": True, "lsp": True, "write_baseline_config": True},
        )

    def test_join_plan_module_child_allows_artifact_evidence_without_source_changes(self) -> None:
        implementation = _plan_module("implementation", title="Implementation")
        final_verification = _plan_module("final_verification", title="Final verification")
        plan = {
            "type": "FinalPlanArtifact",
            "plan_id": "plan_join_artifact_evidence",
            "task_id": "task_join_artifact_evidence",
            "summary": "No-prelude join artifact evidence plan.",
            "modules": [implementation, final_verification],
            "orchestration": {
                "execution_shape": "fork_join_linear",
                "topology": {
                    "nodes": [
                        {"node_id": "node_implementation", "kind": "module", "module_id": "implementation", "depends_on": []},
                        {"node_id": "join", "kind": "join", "module_id": "final_verification", "depends_on": ["node_implementation"]},
                    ],
                    "order": ["node_implementation", "join"],
                },
            },
            "system_test_plan": [{"level": "system", "evidence": "pytest"}],
            "risks": [],
        }

        implementation_pack = self.repository.build_coder_module_pack_from_plan(
            plan,
            module_id="implementation",
            work_order_id="wo_join_artifact_impl",
            workspace={"repo_path": str(self.root)},
        )
        final_pack = self.repository.build_coder_module_pack_from_plan(
            plan,
            module_id="final_verification",
            work_order_id="wo_join_artifact_final",
            workspace={"repo_path": str(self.root)},
        )

        self.assertNotIn("completion_policy", implementation_pack.workspace)
        self.assertTrue(final_pack.workspace["completion_policy"]["allow_artifact_evidence"])
        self.assertEqual(final_pack.workspace["completion_policy"]["artifact_evidence"], "verification_report")

        implementation_resolved = MinionProfileRegistry(runtime_root=self.root).resolve_pack(implementation_pack)
        final_resolved = MinionProfileRegistry(runtime_root=self.root).resolve_pack(final_pack)

        self.assertEqual(implementation_resolved.workspace["completion_policy"]["evidence"], "git_commit")
        self.assertFalse(implementation_resolved.workspace["completion_policy"].get("allow_artifact_evidence", False))
        self.assertEqual(final_resolved.workspace["completion_policy"]["evidence"], "git_commit")
        self.assertTrue(final_resolved.workspace["completion_policy"]["allow_artifact_evidence"])
        self.assertTrue(final_pack.metadata["coder_work_order"]["output_contract"]["verification_only_no_change_allowed"])
        self.assertTrue(final_pack.metadata["coder_work_order"]["output_contract"]["artifact_required_when_no_change"])

    def test_coder_work_order_includes_dependency_public_interfaces(self) -> None:
        module_a = _plan_module("module_a", title="A", task="Do A.")
        module_a["provided_interfaces"] = [
            {
                "name": "module_a.public_api",
                "entrypoint": "pal_dogfood.module_a",
                "contract": "Public API for module B.",
            }
        ]
        module_b = _plan_module("module_b", title="B", task="Use A through its public API.")
        module_b["consumed_interfaces"] = [
            {
                "name": "module_a.public_api",
                "consumer": "module_b",
                "contract": "Module B consumes module A through the declared public API only.",
            }
        ]
        plan = _dispatchable_plan_payload(plan_id="plan_dependency_context", task_id="task_dependency_context", modules=[module_a, module_b])
        nodes = plan["orchestration"]["topology"]["nodes"]
        for node in nodes:
            if node["module_id"] == "module_b":
                node["depends_on"] = ["node_module_a"]
        plan["orchestration"]["topology"]["order"] = ["prelude", "node_module_a", "node_module_b", "join"]

        order = compile_coder_work_order(plan, module_id="module_b", milestone_id="module_b_m1", work_order_id="wo_dep_context")
        prompt_view = prompt_view_for_coder(order).to_dict()

        dependency_modules = [item["module_id"] for item in order.metadata["module_dependency_context"]]
        self.assertIn("module_prelude", dependency_modules)
        self.assertIn("module_a", dependency_modules)
        self.assertTrue(
            any(
                item.get("producer_module_id") == "module_a" and item.get("name") == "module_a.public_api"
                for item in order.relevant_contracts
            )
        )
        self.assertEqual(prompt_view["module"]["dependency_context"], order.metadata["module_dependency_context"])

    def test_plan_parent_completion_advances_parent_cursor_and_waits(self) -> None:
        module_b = _plan_module("module_b", title="B1", task="Do B.")
        module_b["internal_milestones"][0]["milestone_id"] = "b1"
        plan = _dispatchable_plan_payload(
            plan_id="plan_parent_cursor",
            task_id="task_parent_cursor",
            modules=[module_b],
            prelude_module_id="module_a",
        )
        parent = self.repository.build_plan_parent_pack_from_plan(plan, work_order_id="wo_parent_cursor")
        self.repository.prepare_pack_for_spawn(parent)
        child = self.repository.next_plan_module_pack("wo_parent_cursor", allow_paused=True)
        assert child is not None
        self.repository.prepare_pack_for_spawn(child)
        self.repository.update_work_order_workspace(
            child.work_order_id,
            {
                "repo_path": str(self.root / "child_module_repo"),
                "work_order_branch": "work_order_child_module",
                "artifact_dir": str(self.root / "child_module_repo" / "minion_outputs" / child.work_order_id),
            },
        )
        self.repository.record_minion_event(
            {
                "event_kind": "checkpoint",
                "work_order_id": child.work_order_id,
                "payload": {"status": "completed", "milestone_index": 0, "summary": "child done"},
            }
        )
        self.repository.record_minion_event(
            {
                "event_kind": "terminal",
                "work_order_id": child.work_order_id,
                "payload": {"status": "completed", "summary": "child terminal"},
            }
        )
        child_completion = self.repository.mark_serial_module_completed(child.work_order_id)

        parent_completion = self.repository.record_plan_module_completion(child.work_order_id, child_completion)
        snapshot = self.repository.read_work_order("wo_parent_cursor")

        self.assertEqual(parent_completion["status"], "awaiting_continue")
        self.assertTrue(parent_completion["has_next_module"])
        self.assertEqual(parent_completion["next_module_id"], "module_b")
        self.assertEqual(snapshot["current_milestone"]["title"], "module_b")
        self.assertEqual(snapshot["work_order"]["metadata"]["plan_execution"]["status"], "awaiting_continue")
        parent_workspace = snapshot["work_order"]["metadata"]["workspace"]
        self.assertEqual(parent_workspace["source_repo"], str(self.root / "child_module_repo"))
        self.assertEqual(parent_workspace["base_ref"], "work_order_child_module")
        self.assertEqual(parent_workspace["merge_target"], "work_order_child_module")
        self.assertNotIn("artifact_dir", parent_workspace)
        next_child = self.repository.next_plan_module_pack("wo_parent_cursor", allow_paused=True)
        assert next_child is not None
        self.assertEqual(next_child.workspace["source_repo"], str(self.root / "child_module_repo"))
        self.assertEqual(next_child.workspace["base_ref"], "work_order_child_module")

