    def test_coroutine_runner_mode_accepts_manager_control(self) -> None:
        class FakeRunner:
            def __init__(self, **kwargs: Any) -> None:
                self.write_event = kwargs["write_event"]
                self.read_decision = kwargs["read_decision"]

            async def run(self) -> int:
                await self.write_event(
                    {
                        "event_kind": "approval_requested",
                        "payload": {"approval_id": "approval_coroutine", "summary": "needs approval"},
                        "created_at": utc_now(),
                    }
                )
                message = await self.read_decision(1.0)
                if str((message or {}).get("type") or "") != "decision":
                    return 1
                await self.write_event(
                    {
                        "event_kind": "terminal",
                        "payload": {"status": "completed", "summary": "decision received"},
                        "created_at": utc_now(),
                    }
                )
                return 0

        async def scenario() -> None:
            manager = MinionManager(runtime_root=self.root, runner_mode="coroutine")
            with patch("pal.minion.runner.MinionRunner", FakeRunner):
                result = await manager.spawn(
                    TaskContextPack(
                        work_order_id="wo_coroutine_control",
                        goal="Run fake coroutine minion with approval.",
                        minion_profile="generic",
                    ).to_dict()
                )
                state = manager.runs[result["run_id"]]
                for _ in range(50):
                    if state.status == "approval_pending":
                        break
                    await asyncio.sleep(0.01)
                self.assertEqual(state.status, "approval_pending")

                decision = await manager.send_decision(
                    {"approval_id": "approval_coroutine", "decision": "accept", "run_id": state.run_id}
                )
                self.assertTrue(decision["ok"])
                assert state.wait_task is not None
                await state.wait_task

            self.assertEqual(state.status, "completed")
            event_kinds = [event["event_kind"] for event in state.ledger]
            self.assertIn("decision_received", event_kinds)
            self.assertIn("terminal", event_kinds)

        asyncio.run(scenario())

    def test_workspace_file_tools_use_relative_paths_and_cache_safety(self) -> None:
        async def scenario() -> None:
            from pal.execution.file_edit import FileEditTool
            from pal.execution.file_read import FileReadTool
            from pal.execution.file_state import FileStateCache
            from pal.execution.file_write import FileWriteTool
            from pal.execution.path_delete import PathDeleteTool
            from pal.execution.runtime import ExecutionRuntime

            repo_path = self.root / "workspace_file_repo"
            repo_path.mkdir()
            (repo_path / "app.py").write_text("value = 'old'\n", encoding="utf-8")
            cache = FileStateCache()
            runtime = ExecutionRuntime()
            runtime.register_tool(FileReadTool(cache=cache))
            runtime.register_tool(FileEditTool(cache=cache))
            runtime.register_tool(FileWriteTool(cache=cache))
            runtime.register_tool(PathDeleteTool(cache=cache))
            scoped = MinionScopedExecutionRuntime(
                base_runtime=runtime,
                allowed_capabilities=[
                    "op_file_read",
                    "op_file_edit",
                    "op_file_write",
                    "op_path_delete",
                ],
                workspace={"repo_path": str(repo_path)},
            )

            read = await scoped.execute_tool_async(CanonicalToolCall(name="op_file_read", args={"path": "app.py"}, call_id="read_app"))
            self.assertTrue(read.ok, read.text)
            self.assertEqual(read.structured["workspace_path"], "app.py")
            self.assertIn(str(repo_path / "app.py"), cache)

            edit = await scoped.execute_tool_async(
                CanonicalToolCall(
                    name="op_file_edit",
                    args={"path": "app.py", "old_string": "old", "new_string": "new"},
                    call_id="edit_app",
                )
            )
            self.assertTrue(edit.ok, edit.text)
            self.assertEqual((repo_path / "app.py").read_text(encoding="utf-8"), "value = 'new'\n")

            delete = await scoped.execute_tool_async(CanonicalToolCall(name="op_path_delete", args={"path": "app.py"}, call_id="delete_app"))
            self.assertTrue(delete.ok, delete.text)
            self.assertFalse((repo_path / "app.py").exists())

            cache_dir = repo_path / ".pytest_cache"
            cache_dir.mkdir()
            (cache_dir / "nodeids").write_text("cache\n", encoding="utf-8")
            delete_dir = await scoped.execute_tool_async(
                CanonicalToolCall(name="op_path_delete", args={"path": ".pytest_cache", "recursive": True}, call_id="delete_cache")
            )
            self.assertTrue(delete_dir.ok, delete_dir.text)
            self.assertFalse(cache_dir.exists())

            create = await scoped.execute_tool_async(
                CanonicalToolCall(
                    name="op_file_write",
                    args={"path": "nested/result.txt", "content": "done\n"},
                    call_id="write_result",
                )
            )
            self.assertTrue(create.ok, create.text)
            self.assertEqual((repo_path / "nested" / "result.txt").read_text(encoding="utf-8"), "done\n")

        asyncio.run(scenario())

