    def test_manager_logical_slot_rpc_round_trip_over_socket(self) -> None:
        async def scenario() -> None:
            manager, manager_task, client = await self._start_manager(max_parallel_modules=1)
            _ = manager
            try:
                first = await client.request(
                    "request_logical_slot",
                    {"run_id": "run_socket_slot", "work_order_id": "wo_socket_slot", "module_id": "module_a"},
                )
                second = await client.request(
                    "request_logical_slot",
                    {"run_id": "run_socket_slot", "work_order_id": "wo_socket_slot", "module_id": "module_b"},
                )
                wait_task = asyncio.create_task(
                    client.request(
                        "wait_logical_slot",
                        {
                            "run_id": "run_socket_slot",
                            "work_order_id": "wo_socket_slot",
                            "module_id": "module_b",
                            "timeout_seconds": 1.0,
                        },
                    )
                )
                await asyncio.sleep(0.05)
                self.assertFalse(wait_task.done())
                released = await client.request(
                    "release_logical_slot",
                    {"slot_id": first["slot_id"], "run_id": "run_socket_slot", "reason": "done"},
                )
                waited = await asyncio.wait_for(wait_task, timeout=1)
            finally:
                await self._shutdown_manager(client, manager_task)

            self.assertEqual(first["status"], "granted")
            self.assertEqual(second["status"], "denied")
            self.assertEqual(second["reason"], "global_parallel_limit")
            self.assertEqual(released["status"], "released")
            self.assertEqual(waited["status"], "notified")
            self.assertGreaterEqual(waited["available_module_slots"], 1)

        asyncio.run(scenario())

    def test_step_process_supervisor_runs_noop_dag_with_rpc_slots(self) -> None:
        async def scenario() -> None:
            manager, manager_task, client = await self._start_manager(max_parallel_modules=1)
            _ = manager
            payload = {
                "mode": "noop",
                "parent_run_id": "run_step_process_parent",
                "parent_work_order_id": "wo_step_process_parent",
                "modules": {
                    "module_a": TaskContextPack(work_order_id="wo_step_process_a", goal="step a").to_dict(),
                    "module_b": TaskContextPack(work_order_id="wo_step_process_b", goal="step b").to_dict(),
                },
                "depends_on": {"module_a": [], "module_b": []},
                "noop_delay_seconds": 0.05,
            }
            try:
                result = await manager.step_processes.run_once(payload, timeout_seconds=10)
                probe = await client.request(
                    "request_logical_slot",
                    {"run_id": "run_step_process_probe", "work_order_id": "wo_step_process_probe", "module_id": "probe"},
                )
                released = await client.request(
                    "release_logical_slot",
                    {"slot_id": probe.get("slot_id", ""), "run_id": "run_step_process_probe", "reason": "probe_done"},
                )
            finally:
                await self._shutdown_manager(client, manager_task)

            self.assertEqual(result["status"], "completed")
            self.assertEqual(result["completed_modules"], ["module_a", "module_b"])
            self.assertEqual(result["failed_modules"], [])
            self.assertEqual(result["process"]["status"], "completed")
            self.assertFalse(Path(result["process"]["payload_path"]).exists())
            self.assertEqual(probe["status"], "granted")
            self.assertEqual(released["status"], "released")

        asyncio.run(scenario())

    def test_step_process_supervisor_releases_slot_after_timeout(self) -> None:
        async def scenario() -> None:
            manager, manager_task, client = await self._start_manager(max_parallel_modules=1)
            payload = {
                "mode": "noop",
                "parent_run_id": "run_step_process_timeout",
                "parent_work_order_id": "wo_step_process_timeout",
                "modules": {
                    "module_a": TaskContextPack(work_order_id="wo_step_process_timeout_a", goal="step a").to_dict(),
                },
                "depends_on": {"module_a": []},
                "noop_delay_seconds": 10.0,
            }
            try:
                result = await manager.step_processes.run_once(payload, timeout_seconds=2.0)
                probe = await client.request(
                    "request_logical_slot",
                    {"run_id": "run_step_process_timeout_probe", "work_order_id": "wo_step_process_timeout_probe", "module_id": "probe"},
                )
                released = await client.request(
                    "release_logical_slot",
                    {"slot_id": probe.get("slot_id", ""), "run_id": "run_step_process_timeout_probe", "reason": "probe_done"},
                )
            finally:
                await self._shutdown_manager(client, manager_task)

            self.assertEqual(result["status"], "failed")
            self.assertEqual(result["reason"], "step_process_timeout")
            self.assertEqual(result["process"]["status"], "timeout")
            self.assertEqual(probe["status"], "granted")
            self.assertEqual(released["status"], "released")

        asyncio.run(scenario())

    async def _start_manager(self, **manager_kwargs):
        manager = MinionManager(runtime_root=self.root, **manager_kwargs)
        manager_task = asyncio.create_task(manager.run())
        client = MinionManagerClient(runtime_root=self.root, request_timeout_seconds=3.0)
        for _ in range(80):
            try:
                health = await client.request("health")
                if health.get("ok"):
                    return manager, manager_task, client
            except Exception:
                await asyncio.sleep(0.05)
        manager_task.cancel()
        with self.assertRaises(asyncio.CancelledError):
            await manager_task
        self.fail("minion manager did not become healthy")

    async def _shutdown_manager(self, client: MinionManagerClient, task: asyncio.Task) -> None:
        with contextlib.suppress(Exception):
            await client.request("shutdown")
        await asyncio.wait_for(task, timeout=5.0)

    async def _subscribe_events(self):
        reader, writer = await open_manager_connection(self.root)
        request_id = "sub-test"
        writer.write(
            pack_sidecar_message(
                {
                    "type": "request",
                    "id": request_id,
                    "method": "subscribe_events",
                    "params": {},
                }
            )
        )
        await writer.drain()
        response = await asyncio.wait_for(read_sidecar_message(reader), timeout=2)
        self.assertTrue(response.get("ok"), response)
        self.assertEqual(response.get("id"), request_id)
        return reader, writer

    async def _read_subscribed_until(self, reader, predicate) -> dict:
        seen = []
        for _ in range(120):
            try:
                frame = await asyncio.wait_for(read_sidecar_message(reader), timeout=0.5)
            except asyncio.TimeoutError:
                continue
            if str(frame.get("type") or "") != "event":
                continue
            event = frame.get("event")
            if not isinstance(event, dict):
                continue
            seen.append(event)
            if predicate(event):
                return event
        self.fail(f"expected minion event not observed; seen={seen}")

    async def _close_subscription(self, writer) -> None:
        writer.close()
        with contextlib.suppress(Exception):
            await writer.wait_closed()


